SELECT status, close_reason, COUNT(*) AS n, SUM(realized_pnl > 0) AS wins, SUM(realized_pnl < 0) AS losses, ROUND(SUM(realized_pnl), 6) AS sum_pnl, ROUND(AVG(realized_pnl), 6) AS avg_pnl, ROUND(AVG((take_profit - entry_price) / entry_price * 100), 4) AS avg_tp_pct, ROUND(AVG((entry_price - stop_loss) / entry_price * 100), 4) AS avg_sl_pct, ROUND(AVG((take_profit - entry_price) / NULLIF(entry_price - stop_loss, 0)), 4) AS avg_rr FROM crypto_ai.paper_position WHERE opened_at >= '2026-10-11 00:00:00' AND status IN ('CLOSED', 'STOPPED') GROUP BY status, close_reason ORDER BY status, n DESC;